//! [MANTLE] Mantle Hoodi BVM upgrade.
//!
//! Mantle Hoodi's genesis was generated by an `L2Genesis` script that etched `BVM_ETH` without
//! running its constructor (empty immutables and name/symbol) and never wrote `LegacyERC20MNT`
//! (`BVM_MNT`). Neither address is a proxy and no transaction can place code at a fixed address, so
//! the `HoodiBvmUpgrade` hardfork issues an irregular state transition that writes the correct
//! runtime code before any transaction of a block executes, like Canyon's create2 deployer.
//!
//! The write happens once, in the activation block: the first block that is active while the
//! block one [`MANTLE_HOODI_BLOCK_TIME`] earlier is not, as Canyon's `ensure_create2_deployer`
//! does. op-geth (`consensus/misc/hoodi_bvm_upgrade.go`) uses the same condition, so both clients
//! write in the same block whether or not the activation timestamp equals a block timestamp.
//! Storage, balance and nonce are left untouched, so `BVM_ETH` balances and total supply are
//! preserved; `name()`/`symbol()` are constant overrides in both contracts.
//!
//! The bytecode is the runtime code of `BVM_ETH` and of `LegacyERC20MNT` constructed with Hoodi's
//! L1 MNT address `0xb57837B4D0d372bF49E69Bc36c36d9Cc9488bf18`, compiled from
//! `packages/contracts-bedrock` (solc 0.8.15). `test/HoodiBvmUpgradeBytecode.t.sol` rebuilds both
//! contracts and checks them against the code hashes below.

use alloy_evm::Database;
use alloy_op_hardforks::{MANTLE_HOODI_BLOCK_TIME, MANTLE_HOODI_CHAIN_ID, OpHardforks};
use alloy_primitives::{Address, B256, Bytes, address, b256, hex};
use revm::{DatabaseCommit, primitives::HashMap, state::Bytecode};

/// The `BVM_ETH` predeploy address.
pub const BVM_ETH_ADDR: Address = address!("0xdEAddEaDdeadDEadDEADDEAddEADDEAddead1111");

/// The `LegacyERC20MNT` (`BVM_MNT`) predeploy address.
pub const LEGACY_ERC20_MNT_ADDR: Address = address!("0xDeadDeAddeAddEAddeadDEaDDEAdDeaDDeAD0000");

/// The code hash of the `BVM_ETH` runtime code written by the upgrade.
pub const BVM_ETH_CODEHASH: B256 =
    b256!("0xe84a8d4d3ed629a670b03e88dab806078de4b86beac8ca06addcff8dd4996290");

/// The code hash of the `LegacyERC20MNT` runtime code written by the upgrade (Mantle Hoodi only).
pub const LEGACY_ERC20_MNT_CODEHASH: B256 =
    b256!("0xf165e4b851dc8d4e18dcf1d2bc59817d0129a39365c191e76bfd596b60513b45");

/// The `BVM_ETH` runtime code written by the upgrade, hex-encoded.
const BVM_ETH_BYTECODE: &str = include_str!("bytecode/bvm_eth.hex");

/// The `LegacyERC20MNT` runtime code written by the upgrade, with Mantle Hoodi's L1 MNT address,
/// hex-encoded.
const LEGACY_ERC20_MNT_BYTECODE: &str = include_str!("bytecode/legacy_erc20_mnt.hex");

/// Decodes a hex-encoded runtime code embedded above.
fn decode_bytecode(code: &str) -> Bytes {
    hex::decode(code.trim()).expect("embedded BVM predeploy bytecode is valid hex").into()
}

/// Writes the `BVM_ETH` and `LegacyERC20MNT` runtime code on Mantle Hoodi in the activation block
/// of the [`HoodiBvmUpgrade`](alloy_op_hardforks::MantleHardfork::HoodiBvmUpgrade) fork.
pub(crate) fn ensure_bvm_predeploys<DB>(
    chain_spec: impl OpHardforks,
    chain_id: u64,
    timestamp: u64,
    db: &mut DB,
) -> Result<(), DB::Error>
where
    DB: Database + DatabaseCommit,
{
    if chain_id != MANTLE_HOODI_CHAIN_ID ||
        !chain_spec.is_mantle_hoodi_bvm_upgrade_active_at_timestamp(timestamp) ||
        chain_spec.is_mantle_hoodi_bvm_upgrade_active_at_timestamp(
            timestamp.saturating_sub(MANTLE_HOODI_BLOCK_TIME),
        )
    {
        return Ok(());
    }

    let mut changes = HashMap::default();
    for (addr, code_hash, code) in [
        (BVM_ETH_ADDR, BVM_ETH_CODEHASH, BVM_ETH_BYTECODE),
        (LEGACY_ERC20_MNT_ADDR, LEGACY_ERC20_MNT_CODEHASH, LEGACY_ERC20_MNT_BYTECODE),
    ] {
        let mut acc_info = db.basic(addr)?.unwrap_or_default();
        acc_info.code_hash = code_hash;
        acc_info.code = Some(Bytecode::new_raw(decode_bytecode(code)));

        let mut revm_acc: revm::state::Account = acc_info.into();
        revm_acc.mark_touch();
        changes.insert(addr, revm_acc);
    }
    db.commit(changes);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloy_hardforks::{EthereumHardfork, EthereumHardforks, ForkCondition};
    use alloy_op_hardforks::OpHardfork;
    use alloy_primitives::{U256, keccak256};
    use revm::{
        Database as _,
        database::{CacheDB, EmptyDB},
        state::AccountInfo,
    };

    const UPGRADE_TIME: u64 = 1_000;

    /// Spec with only the `HoodiBvmUpgrade` fork scheduled.
    #[derive(Clone, Copy)]
    struct UpgradeSpec(Option<u64>);

    impl EthereumHardforks for UpgradeSpec {
        fn ethereum_fork_activation(&self, _: EthereumHardfork) -> ForkCondition {
            ForkCondition::Never
        }
    }

    impl OpHardforks for UpgradeSpec {
        fn op_fork_activation(&self, _: OpHardfork) -> ForkCondition {
            ForkCondition::Never
        }

        fn is_mantle_hoodi_bvm_upgrade_active_at_timestamp(&self, timestamp: u64) -> bool {
            self.0.is_some_and(|t| timestamp >= t)
        }
    }

    /// Hoodi-like state: `BVM_ETH` holds constructor-less code plus balances, `BVM_MNT` is absent.
    fn hoodi_db() -> CacheDB<EmptyDB> {
        let mut db = CacheDB::new(EmptyDB::default());
        db.insert_account_info(
            BVM_ETH_ADDR,
            AccountInfo {
                code: Some(Bytecode::new_raw(Bytes::from_static(&[0x60, 0x00]))),
                code_hash: keccak256([0x60, 0x00]),
                ..Default::default()
            },
        );
        db.insert_account_storage(BVM_ETH_ADDR, U256::from(2), U256::from(15_349)).unwrap();
        db
    }

    fn code_hash(db: &mut CacheDB<EmptyDB>, addr: Address) -> Option<B256> {
        db.basic(addr).unwrap().map(|acc| acc.code_hash)
    }

    #[test]
    fn code_hashes_match_bytecode() {
        let bvm_eth = decode_bytecode(BVM_ETH_BYTECODE);
        let legacy_erc20_mnt = decode_bytecode(LEGACY_ERC20_MNT_BYTECODE);
        assert_eq!((bvm_eth.len(), legacy_erc20_mnt.len()), (5334, 3521));
        assert_eq!(keccak256(bvm_eth), BVM_ETH_CODEHASH);
        assert_eq!(keccak256(legacy_erc20_mnt), LEGACY_ERC20_MNT_CODEHASH);
    }

    #[test]
    fn writes_both_predeploys_at_activation_block() {
        let mut db = hoodi_db();
        ensure_bvm_predeploys(
            UpgradeSpec(Some(UPGRADE_TIME)),
            MANTLE_HOODI_CHAIN_ID,
            UPGRADE_TIME,
            &mut db,
        )
        .unwrap();

        assert_eq!(code_hash(&mut db, BVM_ETH_ADDR), Some(BVM_ETH_CODEHASH));
        assert_eq!(code_hash(&mut db, LEGACY_ERC20_MNT_ADDR), Some(LEGACY_ERC20_MNT_CODEHASH));
        let mnt = db.basic(LEGACY_ERC20_MNT_ADDR).unwrap().unwrap();
        assert_eq!(mnt.code.unwrap().original_bytes(), decode_bytecode(LEGACY_ERC20_MNT_BYTECODE));
        assert_eq!((mnt.nonce, mnt.balance), (0, U256::ZERO));
        // `BVM_ETH` storage (balances, total supply) is preserved.
        assert_eq!(db.storage(BVM_ETH_ADDR, U256::from(2)).unwrap(), U256::from(15_349));
    }

    /// An activation timestamp between two blocks activates in the next block.
    #[test]
    fn writes_in_first_block_after_unaligned_activation() {
        let mut db = hoodi_db();
        ensure_bvm_predeploys(
            UpgradeSpec(Some(UPGRADE_TIME + 1)),
            MANTLE_HOODI_CHAIN_ID,
            UPGRADE_TIME + MANTLE_HOODI_BLOCK_TIME,
            &mut db,
        )
        .unwrap();
        assert_eq!(code_hash(&mut db, BVM_ETH_ADDR), Some(BVM_ETH_CODEHASH));
        assert_eq!(code_hash(&mut db, LEGACY_ERC20_MNT_ADDR), Some(LEGACY_ERC20_MNT_CODEHASH));
    }

    /// Times near zero saturate the previous block time at zero, as op-geth does.
    #[test]
    fn near_zero_timestamps() {
        for (upgrade, timestamp, write) in [
            (0, 0, false),
            (0, 1, false),
            (0, 2, false),
            (1, 1, true),
            (1, 2, true),
            (2, 2, true),
            (2, 3, true),
            (2, 4, false),
        ] {
            let mut db = hoodi_db();
            ensure_bvm_predeploys(
                UpgradeSpec(Some(upgrade)),
                MANTLE_HOODI_CHAIN_ID,
                timestamp,
                &mut db,
            )
            .unwrap();
            assert_eq!(
                code_hash(&mut db, LEGACY_ERC20_MNT_ADDR).is_some(),
                write,
                "T={upgrade} timestamp={timestamp}"
            );
        }
    }

    /// Blocks after the activation block never write, even if the code is still missing.
    #[test]
    fn noop_after_activation_block() {
        let mut db = hoodi_db();
        ensure_bvm_predeploys(
            UpgradeSpec(Some(UPGRADE_TIME)),
            MANTLE_HOODI_CHAIN_ID,
            UPGRADE_TIME + MANTLE_HOODI_BLOCK_TIME,
            &mut db,
        )
        .unwrap();
        assert_eq!(code_hash(&mut db, BVM_ETH_ADDR), Some(keccak256([0x60, 0x00])));
        assert_eq!(code_hash(&mut db, LEGACY_ERC20_MNT_ADDR), None);
    }

    #[test]
    fn noop_before_activation() {
        let mut db = hoodi_db();
        ensure_bvm_predeploys(
            UpgradeSpec(Some(UPGRADE_TIME)),
            MANTLE_HOODI_CHAIN_ID,
            UPGRADE_TIME - 1,
            &mut db,
        )
        .unwrap();
        assert_eq!(code_hash(&mut db, BVM_ETH_ADDR), Some(keccak256([0x60, 0x00])));
        assert_eq!(code_hash(&mut db, LEGACY_ERC20_MNT_ADDR), None);
    }

    #[test]
    fn noop_when_not_scheduled() {
        let mut db = hoodi_db();
        ensure_bvm_predeploys(UpgradeSpec(None), MANTLE_HOODI_CHAIN_ID, u64::MAX, &mut db).unwrap();
        assert_eq!(code_hash(&mut db, LEGACY_ERC20_MNT_ADDR), None);
    }

    #[test]
    fn noop_on_other_chains() {
        for chain_id in [5000, 5003, 1337] {
            let mut db = hoodi_db();
            ensure_bvm_predeploys(UpgradeSpec(Some(UPGRADE_TIME)), chain_id, UPGRADE_TIME, &mut db)
                .unwrap();
            assert_eq!(code_hash(&mut db, BVM_ETH_ADDR), Some(keccak256([0x60, 0x00])));
            assert_eq!(code_hash(&mut db, LEGACY_ERC20_MNT_ADDR), None);
        }
    }

    /// Counts commits so the single write can be asserted without comparing cache internals.
    #[derive(Debug)]
    struct CountingDb {
        inner: CacheDB<EmptyDB>,
        commits: usize,
    }

    impl revm::Database for CountingDb {
        type Error = core::convert::Infallible;

        fn basic(&mut self, address: Address) -> Result<Option<AccountInfo>, Self::Error> {
            self.inner.basic(address)
        }

        fn code_by_hash(&mut self, code_hash: B256) -> Result<Bytecode, Self::Error> {
            self.inner.code_by_hash(code_hash)
        }

        fn storage(&mut self, address: Address, index: U256) -> Result<U256, Self::Error> {
            self.inner.storage(address, index)
        }

        fn block_hash(&mut self, number: u64) -> Result<B256, Self::Error> {
            self.inner.block_hash(number)
        }
    }

    impl DatabaseCommit for CountingDb {
        fn commit(&mut self, changes: revm::state::EvmState) {
            self.commits += 1;
            self.inner.commit(changes);
        }
    }

    #[test]
    fn writes_only_in_activation_block() {
        let mut db = CountingDb { inner: hoodi_db(), commits: 0 };
        let spec = UpgradeSpec(Some(UPGRADE_TIME));
        for timestamp in (UPGRADE_TIME - MANTLE_HOODI_BLOCK_TIME..=
            UPGRADE_TIME + 3 * MANTLE_HOODI_BLOCK_TIME)
            .step_by(MANTLE_HOODI_BLOCK_TIME as usize)
        {
            ensure_bvm_predeploys(spec, MANTLE_HOODI_CHAIN_ID, timestamp, &mut db).unwrap();
        }
        assert_eq!(db.commits, 1, "only the activation block writes");
    }
}
